import cv2
import numpy as np

def process_images(image_paths: List[str], filters: Dict[str, Dict[str, Any]] = {}) -> Dict[str, Image.Image]:
    images = {}

    for path in image_paths:
        filepath = os.path.join("images", path)
        filename = os.path.splitext(os.path.basename(filepath))[0]

        if filename in filters:
            image = Image.open(filepath)

            if 'filter' in filters[filename]:
                if filters[filename]['filter'] == 'cartoon':
                    image = cartoon(image)

            images[filename] = image

    return images

def cartoon(image) -> Image:
    img = np.array(image)

    gray = cv2.cvtColor(img, cv2.COLOR_RGB2GRAY)
    gray = cv2.medianBlur(gray, 5)
    edges = cv2.adaptiveThreshold(gray, 255, cv2.ADAPTIVE_THRESH_MEAN_C, cv2.THRESH_BINARY, 9, 2)
    color = cv2.bilateralFilter(img, 9, 300, 300)
    cartoon = cv2.bitwise_and(color, color, mask=edges)

    return Image.fromarray(cartoon)

