def parse_csv(csv_line: str) -> List[float]:
    values = csv_line.split(',')
    return [float(v.strip()) for v in values]

def get_womens_men_avg_height(csv_content: str) -> str:
    womens_heights = []
    mens_heights = []

    for line in csv_content.splitlines():
        height_data = parse_csv(line)
        if len(height_data) == 4:
            avg_height = height_data[1]
            gender = height_data[2]

            if gender == 1:
                mens_heights.append(avg_height)
            else:
                womens_heights.append(avg_height)

    avg_womens_height = sum(womens_heights) / len(womens_heights)
    avg_mens_height = sum(mens_heights) / len(mens_heights)

    return f"Average women's height: {avg_womens_height}, Average men's height: {avg_mens_height}"

